const headers = $input.first().json.headers || {};
const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const token = String(lower['x-tradesejon-secret'] || lower['x-operator-token'] || lower['x-ceo-token'] || '');
const expected = String($env.WORKSHOP_LAUNCH_TOKEN || $env.TRADESAJON_BRIDGE_SECRET || '');
if (!expected || token !== expected) {
  return [{ json: { ok: false, authorized: false, httpStatus: 401, error: 'unauthorized' } }];
}
const body = $input.first().json.body || $input.first().json || {};
return [{ json: { ok: true, authorized: true, body } }];

const item = $input.first().json;
if (!item.authorized) return [{ json: item }];
const b = item.body || {};
const targetId = String(b.discord_user_id || '');
const msg = String(b.message || '');
const token = $env.DISCORD_BOT_TOKEN || '';
if (!targetId || !msg || !token) return [{ json: { ok: false, httpStatus: 400, error: 'Missing discord_user_id, message, or DISCORD_BOT_TOKEN' } }];
const ch = await fetch('https://discord.com/api/v10/users/@me/channels', {
  method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ recipient_id: targetId })
}).then(r => r.json());
if (!ch.id) return [{ json: { ok: false, delivered: false, httpStatus: 502, error: 'Failed to open Discord DM channel' } }];
const sent = await fetch(`https://discord.com/api/v10/channels/${ch.id}/messages`, {
  method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ content: msg })
}).then(r => r.json());
return [{ json: { ok: Boolean(sent.id), delivered: Boolean(sent.id), messageId: sent.id || null } }];
